#include <rns8/rns8.h>
#include <stdint.h>
_Static_assert(sizeof(rns8_adaptive_summary_info)==80,"summary observation ABI");
int main(void) {
  rns8_context_options options={0};rns8_context* ctx=0;
  rns8_gemm_desc d={0};rns8_plan* plan=0;rns8_workspace* work=0;
  rns8_adaptive_summary_info info={0};rns8_matrix_desc md={0};
  rns8_matrix *a=0,*b=0,*c=0;int64_t input=1,old=42;uint64_t output[3]={0};
  options.struct_size=sizeof(options);options.abi_version=RNS8_ABI_VERSION;
  options.requested_backend=RNS8_BACKEND_CPU_REFERENCE;
  if(rns8_create_context(-1,&options,&ctx)!=RNS8_SUCCESS)return 1;
  d.struct_size=sizeof(d);d.abi_version=RNS8_ABI_VERSION;d.semantics=RNS8_EXACT_WIDE_SIGNED;
  d.bound_kind=RNS8_BOUND_NONE;d.requested_backend=RNS8_BACKEND_CPU_REFERENCE;
  d.m=d.n=d.k=1;d.max_prefix=20;d.flags=RNS8_PLAN_EXACT_VALUE_BOUND|RNS8_PLAN_FORCE_FIXED_PREFIX;
  if(rns8_create_plan(ctx,&d,&plan)!=RNS8_SUCCESS)return 2;
  if(rns8_create_workspace(ctx,plan,&work)!=RNS8_SUCCESS)return 3;
  info.struct_size=sizeof(info);info.abi_version=RNS8_ABI_VERSION;
  if(rns8_get_adaptive_summary_info(work,&info)!=RNS8_SUCCESS || info.retained_bytes || info.a_scans || info.b_reuses)return 4;
  md.struct_size=sizeof(md);md.abi_version=RNS8_ABI_VERSION;md.semantics=d.semantics;md.bound_kind=d.bound_kind;
  md.rows=md.cols=md.logical_ld=1;md.logical_layout=RNS8_LAYOUT_ROW_MAJOR;md.max_prefix=20;
  if(rns8_create_matrix(ctx,&md,&a)!=RNS8_SUCCESS || rns8_create_matrix(ctx,&md,&b)!=RNS8_SUCCESS || rns8_create_matrix(ctx,&md,&c)!=RNS8_SUCCESS)return 5;
  if(rns8_pack_i64(ctx,a,&input,1,0)!=RNS8_SUCCESS || rns8_pack_i64(ctx,b,&input,1,0)!=RNS8_SUCCESS || rns8_pack_i64(ctx,c,&old,1,0)!=RNS8_SUCCESS)return 6;
  if(rns8_gemm_adaptive_exact_cached(ctx,plan,a,b,c,RNS8_ADAPTIVE_AXIS_L1,256,2,32,UINT64_MAX,work)!=RNS8_UNSUPPORTED_BACKEND)return 7;
  if(rns8_export_exact_wide_signed_limbs(ctx,plan,c,output,1,3)!=RNS8_SUCCESS || output[0]!=42 || output[1] || output[2])return 8;
  if(rns8_destroy_matrix(c)!=RNS8_SUCCESS || rns8_destroy_matrix(b)!=RNS8_SUCCESS || rns8_destroy_matrix(a)!=RNS8_SUCCESS)return 9;
  if(rns8_destroy_workspace(work)!=RNS8_SUCCESS || rns8_destroy_plan(plan)!=RNS8_SUCCESS)return 10;
  return rns8_destroy_context(ctx)==RNS8_SUCCESS?0:11;
}
